  $("hfCapture").onclick = hfSendCapture;
  $("hfRelease").onclick = hfSendRelease;

  var hfView = $("view3d");
  function hfLocal(ev) { var r = hfView.getBoundingClientRect();
    return { x: ev.clientX - r.left, y: ev.clientY - r.top }; }
