  var banner = $("hfBanner");
  if (banner) {
    var synthetic = PREFIX.indexOf("verify") >= 0 || POINTS_TOPIC.indexOf("verify") >= 0;
    banner.textContent = "人体跌倒 · " + PREFIX + " · " +
      (synthetic ? "合成/验证输入（非真实人体）" : "几何模式") + " · 未验收不产生 confirmed";
  }
