/* ---------- 消息分发与统计 ---------- */
function handleMessage(topic, logTimeNs, payload) {
  if (rec) rec.add(topic, logTimeNs, payload);
  if (topic === HF_POINTS_TOPIC) {
    $("pcHz").textContent = ratePc().toFixed(1);
    pcBytesAcc += payload.byteLength;
    const now = Date.now();
    if (now - pcBwT0 >= 1000) {              // 1s 窗口平滑吞吐
      $("pcBW").textContent = (pcBytesAcc * 1000 / (now - pcBwT0) / 1048576).toFixed(1);
      pcBytesAcc = 0; pcBwT0 = now;
    }
    $("lastT").textContent = new Date(Number(logTimeNs) / 1e6).toLocaleTimeString("zh-CN", { hour12: false });
    onPointCloud(logTimeNs, payload);
  } else if (topic === "/inno_imu") {
    onImu(payload);
  } else if (topic === "/device_status") {
    onDevStatus(payload);
  }
}

