/* ---------- 消息分发与统计 ---------- */
// Raw receive statistics for one cloud message. Kept separate from rendering so
// the HF layer can count raw arrival and presented rate independently: raw seq
// gaps are counted here, while only the chosen (output-matched) frame is
// rendered via renderPoints().
function recordPointsStats(logTimeNs, payload) {
  if (rec) rec.add(HF_POINTS_TOPIC, logTimeNs, payload);
  $("pcHz").textContent = ratePc().toFixed(1);
  pcBytesAcc += payload.byteLength;
  const now = Date.now();
  if (now - pcBwT0 >= 1000) {              // 1s 窗口平滑吞吐
    $("pcBW").textContent = (pcBytesAcc * 1000 / (now - pcBwT0) / 1048576).toFixed(1);
    pcBytesAcc = 0; pcBwT0 = now;
  }
  $("lastT").textContent = new Date(Number(logTimeNs) / 1e6).toLocaleTimeString("zh-CN", { hour12: false });
  // seq 连续性统计（u32 全宽差值；回绕/清零按重同步处理，不计丢帧）
  if (payload.byteLength >= 12) {
    try {
      const seq = new DataView(payload.buffer, payload.byteOffset, payload.byteLength).getUint32(0, true);
      if (pcPrevSeq !== null) {
        const d = (seq - pcPrevSeq) >>> 0;
        if (d > 1 && d < 0x80000000) { pcDrops += d - 1; $("pcDrop").textContent = pcDrops; }
      }
      pcPrevSeq = seq;
    } catch (e) { /* header unavailable: skip drop accounting for this frame */ }
  }
}
// Render one (chosen) cloud frame into the shared point buffers.
function renderPoints(logTimeNs, payload) { onPointCloud(logTimeNs, payload); }
function handleMessage(topic, logTimeNs, payload) {
  if (topic === HF_POINTS_TOPIC) {
    recordPointsStats(logTimeNs, payload);
    renderPoints(logTimeNs, payload);
  } else if (topic === "/inno_imu") {
    if (rec) rec.add(topic, logTimeNs, payload);
    onImu(payload);
  } else if (topic === "/device_status") {
    if (rec) rec.add(topic, logTimeNs, payload);
    onDevStatus(payload);
  }
}

